  "ch4.dll.n": "The paper's {v}",
  "ch4.dll.b": "PCIe essay, ch. 10: {v}",
  "ch4.tbl.aria": "PCIe bytes for each item of one packet, in both directions",
  "ch4.th.item": "Per packet",
  "ch4.th.up": "Card → host",
  "ch4.th.down": "Host → card",
